const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);
const results = data.filter(r =>
  r.Customer === 'Maya Chen' &&
  r.Date === '2026-09-02' &&
  (r.Status === 'cancelled' || r.Status === 'confirmed')
);
console.log('Found', results.length, 'matching orders:\n');
results.forEach(r => {
  console.log('  Order ID   :', r['Order ID']);
  console.log('  Customer   :', r.Customer);
  console.log('  Date       :', r.Date);
  console.log('  Status     :', r.Status);
  console.log('  Items      :', r.Items);
  console.log('  Total Paid : \$' + r['Total Paid']);
  console.log();
});
"
